script:
// Utility function to get initials from a name
function getInitials(name) {
    if (!name) return "";
    return name.split(" ").map(part => part[0]).join("").toUpperCase();
}

// Total Employees
frappe.call({
    method: 'frappe.client.get_count',
    args: { doctype: 'Employee', filters: { status: 'Active' } },
    callback: function(r) {
        root_element.querySelector('#totalEmployees').textContent = r.message ?? '0';
    }
});

// Available Employees
frappe.call({
    method: 'one_compliance.one_compliance.workspace.employee_management.employee_management.get_available_employees_today',
    callback: function(r) {
        root_element.querySelector('#availableCount').textContent = r.message ?? '0';
    }
});

// Employees on Leave
frappe.call({
    method: "one_compliance.one_compliance.workspace.employee_management.employee_management.get_employees_on_leave_today",
    callback: function(r) {
        root_element.querySelector('#onLeaveCount').textContent = r.message ?? '0';
    }
});

// Work From Home Employees
frappe.call({
    method: "one_compliance.one_compliance.workspace.employee_management.employee_management.get_work_from_home_employees_today",
    callback: function(r) {
        root_element.querySelector('#workFromHomeCount').textContent = r.message ?? '0';
    }
});

// On Duty Employees
frappe.call({
    method: "one_compliance.one_compliance.workspace.employee_management.employee_management.get_on_duty_employees_today",
    callback: function(r) {
        root_element.querySelector('#onDutyCount').textContent = r.message ?? '0';
    }
});

// Get all employees with status and populate the list
frappe.call({
    method: 'one_compliance.one_compliance.workspace.employee_management.employee_management.get_all_employees_with_status',
    callback: function(r) {
        const container = root_element.querySelector("#employeeList");
        if (!container) return console.error('Employee list container not found');

        container.innerHTML = ""; 

        // Add header row
        const header = document.createElement("div");
        header.className = "employee-list-header";
        header.style.display = "flex";
        header.style.fontWeight = "bold";
        header.style.marginBottom = "0.5rem";
        header.innerHTML = `
            <div style="flex: 1; margin-left: 1.5rem; margin-bottom: 1rem; margin-top: 1rem;">Employee</div>
            <div style="width: 120px; text-align: center; margin-bottom: 1rem; margin-top: 1rem;">Task Weightage</div>
            <div style="width: 150px; text-align: center; margin-bottom: 1rem; margin-top: 1rem;">Status</div>
        `;
        container.appendChild(header);

        const statusLabels = {
            available: "Available",
            on_leave: "On Leave",
            work_from_home: "Work From Home",
            unavailable: "Unavailable",
            on_duty: "On Duty"
        };

        const statusClasses = {
            available: "status-available",
            on_leave: "status-on_leave",
            work_from_home: "status-work_from_home",
            unavailable: "status-unavailable",
            on_duty: "status-on_duty"
        };

        if (!r.message || r.message.length === 0) {
            container.innerHTML += '<div class="no-employees">No employees found</div>';
            return;
        }

        // Sort employees by total_task_weightage (descending)
        const sortedEmployees = r.message.sort((a, b) => (b.total_task_weightage || 0) - (a.total_task_weightage || 0));

        sortedEmployees.forEach(emp => {
            const div = document.createElement("div");
            div.className = "employee-item";
            div.style.display = "flex";
            div.style.alignItems = "center";
            div.style.padding = "0.5rem 0";

            // Generate avatar: image or initials
            const initials = getInitials(emp.employee_name);
            const profileAvatar = emp.profile_image_url 
                ? `<img src="${emp.profile_image_url}" alt="${emp.employee_name}" class="employee-profile-img"
                      onerror="this.style.display='none'; this.nextElementSibling.style.display='flex';" />` 
                : '';

            const initialsDiv = `<div class="employee-initials" style="display:${emp.profile_image_url ? 'none' : 'flex'}">
                                    ${initials}
                                  </div>`;

            const avatarHtml = `
                <div style="width: 50px; height: 50px; display: flex; justify-content: center; align-items: center; border-radius: 50%; background:#ddd; margin-left:1.5rem; font-weight:bold; font-size:14px; color:#333;" class="employee-avatar">
                    ${profileAvatar}
                    ${initialsDiv}
                </div>
            `;

            div.innerHTML = `
                ${avatarHtml}
                <div style="flex: 1;" class="employee-info">
                    <div class="employee-name">${emp.employee_name}</div>
                    <div class="employee-role">${emp.designation || "No designation"}</div>
                </div>
                <div style="width: 120px; text-align: center; font-weight: bold;">
                    ${emp.total_task_weightage || 0}
                </div>
                <div style="width: 100px; text-align: center;" 
                     class="employee-status ${statusClasses[emp.status] || 'status-unavailable'}">
                    ${statusLabels[emp.status] || 'Unknown'}
                </div>
            `;

            div.addEventListener('click', function() {
                showEmployeeDetails(emp);
            });

            container.appendChild(div);
        });
    },
    error: function(err) {
        console.error('Error fetching employees:', err);
        const container = root_element.querySelector("#employeeList");
        if (container) {
            container.innerHTML = '<div class="error-message">Error loading employees</div>';
        }
    }
});

// Search and Filter Functionality
const searchInput = root_element.querySelector('#searchInput-2');
const statusFilter = root_element.querySelector('#statusFilter');

if (searchInput) {
    searchInput.addEventListener('keydown', function(event) { event.stopPropagation(); if (event.key === 'Enter') event.preventDefault(); filterEmployees(); });
    searchInput.addEventListener('input', filterEmployees);
}

if (statusFilter) {
    statusFilter.addEventListener('change', filterEmployees);
}

function filterEmployees() {
    const searchTerm = searchInput ? searchInput.value.toLowerCase() : '';
    const selectedStatus = statusFilter ? statusFilter.value : 'all';
    const employeeItems = root_element.querySelectorAll('.employee-item');

    employeeItems.forEach(item => {
        const employeeName = item.querySelector('.employee-name').textContent.toLowerCase();
        const employeeRole = item.querySelector('.employee-role').textContent.toLowerCase();
        const employeeStatus = item.querySelector('.employee-status');

        const matchesSearch = employeeName.includes(searchTerm) || employeeRole.includes(searchTerm);
        const matchesStatus = selectedStatus === 'all' || employeeStatus.classList.contains(`status-${selectedStatus}`);

        item.style.display = (matchesSearch && matchesStatus) ? 'flex' : 'none';
    });
}

// Show Employee Details
function showEmployeeDetails(employee) {
    const detailsSection = root_element.querySelector('#employeeDetails');
    const detailsHeader = root_element.querySelector('#detailsHeader');
    const tasksContainer = root_element.querySelector('#employeeTasks');
    const projectsContainer = root_element.querySelector('#employeeProjects');

    if (!detailsSection || !detailsHeader) return;

    detailsHeader.innerHTML = `
        <h2>${employee.employee_name}</h2>
        <p>${employee.designation || 'No designation'}</p>
    `;
    detailsSection.style.display = 'block';
    tasksContainer.innerHTML = '<div class="loading">Loading tasks...</div>';
    projectsContainer.innerHTML = '<div class="loading">Loading projects...</div>';

    frappe.call({
        method: 'one_compliance.one_compliance.workspace.employee_management.employee_management.get_employee_tasks_today',
        args: { employee_id: employee.email },
        type: 'POST',
        callback: function(r) {
            if (r.message && r.message.length > 0) {
                let tasksHtml = '';
                const projectIds = new Set();

                r.message.forEach(task => {
                    if (task.project) projectIds.add(task.project);
                    tasksHtml += `
                        <div class="task-item">
                            <div class="task-header">
                                <div class="task-title">${task.subject}</div>
                                <div class="task-status-priority">
                                    <div class="task-weightage">${task.task_weightage || 0}</div>
                                    <div class="task-status">${task.status}</div>
                                    <div class="task-badge badge-${task.priority?.toLowerCase() || 'medium'}">
                                        ${task.priority || 'Medium'}
                                    </div>
                                </div>
                            </div>
                        </div>
                    `;
                });

                tasksContainer.innerHTML = tasksHtml;

                if (projectIds.size > 0) fetchEmployeeProjects(Array.from(projectIds), projectsContainer);
                else projectsContainer.innerHTML = '<div class="no-data">No projects associated with today\'s tasks</div>';

            } else {
                tasksContainer.innerHTML = '<div class="no-data">No tasks for today</div>';
                projectsContainer.innerHTML = '<div class="no-data">No projects associated with today\'s tasks</div>';
            }
        },
        error: function() {
            tasksContainer.innerHTML = '<div class="error">Error loading tasks</div>';
            projectsContainer.innerHTML = '<div class="error">Error loading projects</div>';
        }
    });
}

// Fetch Employee Projects
function fetchEmployeeProjects(projectIds, projectsContainer) {
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Project',
            filters: [['name', 'in', projectIds], ['status', 'not in', ['Completed', 'Cancelled']]],
            fields: ['name', 'project_name', 'status', 'priority'],
            order_by: 'project_name ASC'
        },
        callback: function(r) {
            if (r.message && r.message.length > 0) {
                let projectsHtml = '';
                r.message.forEach(project => {
                    projectsHtml += `
                        <div class="project-item">
                            <div class="project-header">
                                <div class="project-name">${project.project_name}</div>
                                <div class="project-status project-${(project.status || 'Open').toLowerCase().replace(/\s+/g, '_')}">
                                    ${project.status || 'Open'}
                                </div>
                            </div>
                        </div>
                    `;
                });
                projectsContainer.innerHTML = projectsHtml;
            } else {
                projectsContainer.innerHTML = '<div class="no-data">No active projects found</div>';
            }
        },
        error: function() {
            projectsContainer.innerHTML = '<div class="error">Error loading projects</div>';
        }
    });
}

